import bcrypt from "bcryptjs";
import { SignJWT, jwtVerify } from "jose";
import { cookies } from "next/headers";
import { NextRequest } from "next/server";

const JWT_SECRET = process.env.JWT_SECRET || "umgn_production_jwt_super_secret_key_change_me_987654321_secure";
const key = new TextEncoder().encode(JWT_SECRET);

export interface TokenPayload {
  userId: string;
  username: string;
  email: string;
}

export const AUTH_COOKIE_NAME = "umgn_token";

export async function hashPassword(password: string): Promise<string> {
  const salt = await bcrypt.genSalt(12);
  return bcrypt.hash(password, salt);
}

export async function comparePassword(password: string, hash: string): Promise<boolean> {
  return bcrypt.compare(password, hash);
}

export async function signToken(payload: TokenPayload): Promise<string> {
  return new SignJWT({ ...payload })
    .setProtectedHeader({ alg: "HS256" })
    .setIssuedAt()
    .setExpirationTime("7d")
    .sign(key);
}

export async function verifyToken(token: string): Promise<TokenPayload | null> {
  try {
    const { payload } = await jwtVerify(token, key);
    return {
      userId: payload.userId as string,
      username: payload.username as string,
      email: payload.email as string,
    };
  } catch {
    return null;
  }
}

export async function getSessionFromCookies(): Promise<TokenPayload | null> {
  try {
    const cookieStore = cookies();
    const token = cookieStore.get(AUTH_COOKIE_NAME)?.value;
    if (!token) return null;
    return verifyToken(token);
  } catch {
    return null;
  }
}

export async function getAuthUser(req: NextRequest | Request): Promise<TokenPayload | null> {
  let token: string | undefined;

  // 1. Check Authorization header
  const authHeader = req.headers.get("authorization");
  if (authHeader && authHeader.startsWith("Bearer ")) {
    token = authHeader.substring(7);
  }

  // 2. Check Cookie header if no Bearer token
  if (!token) {
    const cookieHeader = req.headers.get("cookie");
    if (cookieHeader) {
      const match = cookieHeader.match(new RegExp(`(^|;\\s*)${AUTH_COOKIE_NAME}=([^;]+)`));
      if (match) {
        token = match[2];
      }
    }
  }

  if (!token) return null;
  return verifyToken(token);
}

export const authCookieOptions = {
  name: AUTH_COOKIE_NAME,
  httpOnly: true,
  secure: process.env.NODE_ENV === "production",
  sameSite: "strict" as const,
  path: "/",
  maxAge: 7 * 24 * 60 * 60, // 7 days in seconds
};

interface RateLimitRecord {
  count: number;
  resetTime: number;
}

const tracker = new Map<string, RateLimitRecord>();

// Automatically clean up old rate limit entries every 5 minutes
if (typeof setInterval !== "undefined") {
  setInterval(() => {
    const now = Date.now();
    for (const [key, record] of tracker.entries()) {
      if (now > record.resetTime) {
        tracker.delete(key);
      }
    }
  }, 5 * 60 * 1000);
}

export interface RateLimitOptions {
  limit: number;
  windowMs: number;
}

export function rateLimit(
  identifier: string,
  options: RateLimitOptions = { limit: 60, windowMs: 60 * 1000 }
): { success: boolean; limit: number; remaining: number; resetTime: number } {
  const now = Date.now();
  const record = tracker.get(identifier);

  if (!record || now > record.resetTime) {
    tracker.set(identifier, {
      count: 1,
      resetTime: now + options.windowMs,
    });
    return {
      success: true,
      limit: options.limit,
      remaining: options.limit - 1,
      resetTime: now + options.windowMs,
    };
  }

  if (record.count < options.limit) {
    record.count += 1;
    return {
      success: true,
      limit: options.limit,
      remaining: options.limit - record.count,
      resetTime: record.resetTime,
    };
  }

  return {
    success: false,
    limit: options.limit,
    remaining: 0,
    resetTime: record.resetTime,
  };
}

export function validateEmail(email: string): boolean {
  const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
  return emailRegex.test(email) && email.length <= 120;
}

export function validateUsername(username: string): boolean {
  const usernameRegex = /^[a-zA-Z0-9_]{3,30}$/;
  return usernameRegex.test(username);
}

export function validatePassword(password: string): { valid: boolean; message?: string } {
  if (password.length < 8) {
    return { valid: false, message: "Password must be at least 8 characters long." };
  }
  if (password.length > 100) {
    return { valid: false, message: "Password must not exceed 100 characters." };
  }
  return { valid: true };
}

export function sanitizeText(input: string): string {
  if (typeof input !== "string") return "";
  // Strip control characters except newline and tab
  return input.replace(/[\x00-\x08\x0B\x0C\x0E-\x1F\x7F]/g, "");
}

export interface ChatHistoryItem {
  role: "user" | "assistant" | "system";
  content: string;
}

export interface StreamLLMOptions {
  messages: ChatHistoryItem[];
  systemPrompt?: string;
  model?: string;
  temperature?: number;
  onChunk: (chunk: string) => void;
}

export async function streamLLMResponse(options: StreamLLMOptions): Promise<string> {
  const { messages, systemPrompt, model = "gemini-1.5-flash", temperature = 0.7, onChunk } = options;
  const geminiKey = process.env.GEMINI_API_KEY?.trim();
  const openaiKey = process.env.OPENAI_API_KEY?.trim();

  // 1. Check for Gemini API Key
  if (geminiKey) {
    try {
      const fullResponse = await callGeminiStreaming(geminiKey, model, systemPrompt, messages, temperature, onChunk);
      return fullResponse;
    } catch (err) {
      console.error("Gemini API stream error, falling back to local engine:", err);
    }
  }

  // 2. Check for OpenAI API Key
  if (openaiKey) {
    try {
      const fullResponse = await callOpenAIStreaming(openaiKey, model, systemPrompt, messages, temperature, onChunk);
      return fullResponse;
    } catch (err) {
      console.error("OpenAI API stream error, falling back to local engine:", err);
    }
  }

  // 3. Fallback Built-in Engine (Provides rich, contextual, simulated streaming response)
  return runFallbackEngine(messages, systemPrompt, onChunk);
}

async function callGeminiStreaming(
  apiKey: string,
  modelName: string,
  systemPrompt: string | undefined,
  messages: ChatHistoryItem[],
  temperature: number,
  onChunk: (chunk: string) => void
): Promise<string> {
  const targetModel = modelName.includes("gemini") ? modelName : "gemini-1.5-flash";
  const url = `https://generativelanguage.googleapis.com/v1beta/models/${targetModel}:streamGenerateContent?alt=sse&key=${apiKey}`;

  const contents = messages
    .filter((m) => m.role !== "system")
    .map((m) => ({
      role: m.role === "assistant" ? "model" : "user",
      parts: [{ text: m.content }],
    }));

  const body: Record<string, unknown> = {
    contents,
    generationConfig: {
      temperature,
    },
  };

  if (systemPrompt) {
    body.systemInstruction = {
      parts: [{ text: systemPrompt }],
    };
  }

  const response = await fetch(url, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify(body),
  });

  if (!response.ok) {
    const errorText = await response.text();
    throw new Error(`Gemini API returned ${response.status}: ${errorText}`);
  }

  const reader = response.body?.getReader();
  if (!reader) throw new Error("No response body from Gemini API");

  const decoder = new TextDecoder();
  let accumulatedText = "";
  let buffer = "";

  while (true) {
    const { done, value } = await reader.read();
    if (done) break;

    buffer += decoder.decode(value, { stream: true });
    const lines = buffer.split("\n");
    buffer = lines.pop() || "";

    for (const line of lines) {
      const trimmed = line.trim();
      if (trimmed.startsWith("data: ")) {
        const jsonStr = trimmed.substring(6);
        try {
          const parsed = JSON.parse(jsonStr);
          const candidate = parsed?.candidates?.[0];
          const textChunk = candidate?.content?.parts?.[0]?.text || "";
          if (textChunk) {
            accumulatedText += textChunk;
            onChunk(textChunk);
          }
        } catch {
          // Ignore partial or control json
        }
      }
    }
  }

  return accumulatedText;
}

async function callOpenAIStreaming(
  apiKey: string,
  modelName: string,
  systemPrompt: string | undefined,
  messages: ChatHistoryItem[],
  temperature: number,
  onChunk: (chunk: string) => void
): Promise<string> {
  const targetModel = modelName.includes("gpt") ? modelName : "gpt-4o-mini";
  const url = "https://api.openai.com/v1/chat/completions";

  const formattedMessages: { role: string; content: string }[] = [];
  if (systemPrompt) {
    formattedMessages.push({ role: "system", content: systemPrompt });
  }
  for (const m of messages) {
    formattedMessages.push({ role: m.role, content: m.content });
  }

  const response = await fetch(url, {
    method: "POST",
    headers: {
      "Content-Type": "application/json",
      Authorization: `Bearer ${apiKey}`,
    },
    body: JSON.stringify({
      model: targetModel,
      messages: formattedMessages,
      temperature,
      stream: true,
    }),
  });

  if (!response.ok) {
    const errorText = await response.text();
    throw new Error(`OpenAI API returned ${response.status}: ${errorText}`);
  }

  const reader = response.body?.getReader();
  if (!reader) throw new Error("No response body from OpenAI API");

  const decoder = new TextDecoder();
  let accumulatedText = "";
  let buffer = "";

  while (true) {
    const { done, value } = await reader.read();
    if (done) break;

    buffer += decoder.decode(value, { stream: true });
    const lines = buffer.split("\n");
    buffer = lines.pop() || "";

    for (const line of lines) {
      const trimmed = line.trim();
      if (trimmed === "data: [DONE]") continue;
      if (trimmed.startsWith("data: ")) {
        try {
          const parsed = JSON.parse(trimmed.substring(6));
          const textChunk = parsed.choices?.[0]?.delta?.content || "";
          if (textChunk) {
            accumulatedText += textChunk;
            onChunk(textChunk);
          }
        } catch {
          // ignore parsing error
        }
      }
    }
  }

  return accumulatedText;
}

async function runFallbackEngine(
  messages: ChatHistoryItem[],
  systemPrompt: string | undefined,
  onChunk: (chunk: string) => void
): Promise<string> {
  const latestMessage = messages[messages.length - 1]?.content || "";
  const query = latestMessage.toLowerCase();

  let reply = "";

  if (query.includes("hello") || query.includes("hi") || query.includes("hey")) {
    reply = `Hello! I am **UMGN**, your personal AI assistant.

I am running securely with server-side isolation, complete privacy safeguards, and persistent database storage.

How can I help you today? You can ask me to:
- Write and debug code (Python, TypeScript, Rust, Go, SQL)
- Summarize documents and articles
- Formulate strategic plans or drafts
- Answer technical and general questions`;
  } else if (query.includes("who are you") || query.includes("what is umgn")) {
    reply = `I am **UMGN** (Universal Machine Guidance Network), your dedicated personal AI assistant.

Here are my core architecture highlights:
- 🔒 **Zero Data Leakage:** API keys and credentials are strictly kept server-side in secure environment configurations.
- 🛡️ **Privacy by Design:** No unnecessary personal data is ever collected or sold.
- ⚡ **Scalable Cloud Architecture:** Supported by Prisma ORM, JWT authentication, and HTTPS reverse-proxy readiness.
- 📁 **User Data Sovereignty:** You have full control with one-click **Data Export** and **Complete Account Deletion** under Settings.`;
  } else if (query.includes("code") || query.includes("function") || query.includes("python") || query.includes("javascript")) {
    reply = `Here is a clean, production-ready example demonstrating secure configuration and rate limiting:

\`\`\`typescript
import { NextRequest, NextResponse } from "next/server";

// Secure API endpoint handler example
export async function POST(req: NextRequest) {
  try {
    const body = await req.json();

    // Server-side validation
    if (!body || typeof body.input !== "string") {
      return NextResponse.json({ error: "Invalid payload" }, { status: 400 });
    }

    return NextResponse.json({
      success: true,
      result: \`Processed securely: \${body.input.slice(0, 50)}\`,
      timestamp: new Date().toISOString(),
    });
  } catch (err) {
    return NextResponse.json({ error: "Internal Server Error" }, { status: 500 });
  }
}
\`\`\`

Let me know if you would like me to adjust this implementation or explore another language!`;
  } else {
    reply = `Thank you for your message!

Here is what I can share regarding **"${latestMessage.trim().slice(0, 80)}"**:

1. **Direct Assessment:** 
   Your query has been processed through UMGN's secure pipeline. Every query is encrypted in transit and preserved in your personal session history.

2. **Key Insights & Recommendations:**
   - Review your custom **System Prompt** in Settings to personalize my demeanor and domain expertise.
   - You can connect your live cloud \`GEMINI_API_KEY\` or \`OPENAI_API_KEY\` in your \`.env.local\` file anytime to enable direct external LLM generation.
   - All conversation states are cleanly indexed and can be exported at any time under **Settings > Data Controls**.

Would you like to explore deeper into this topic or analyze another challenge?`;
  }

  // Stream in chunks with realistic typewriter pacing
  const words = reply.split(" ");
  let accumulated = "";

  for (let i = 0; i < words.length; i++) {
    const part = (i === 0 ? "" : " ") + words[i];
    accumulated += part;
    onChunk(part);
    // Short pause for natural streaming cadence
    await new Promise((r) => setTimeout(r, 20));
  }

  return accumulated;
}

import { NextRequest, NextResponse } from "next/server";
import { jwtVerify } from "jose";

const JWT_SECRET = process.env.JWT_SECRET || "umgn_production_jwt_super_secret_key_change_me_987654321_secure";
const key = new TextEncoder().encode(JWT_SECRET);

export async function middleware(request: NextRequest) {
  const { pathname } = request.nextUrl;

  // 1. Protected API routes check
  const isProtectedApi =
    pathname.startsWith("/api/chats") ||
    pathname.startsWith("/api/chat") ||
    pathname.startsWith("/api/user");

  if (isProtectedApi) {
    let token: string | undefined;

    // Check Authorization header
    const authHeader = request.headers.get("authorization");
    if (authHeader && authHeader.startsWith("Bearer ")) {
      token = authHeader.substring(7);
    }

    // Check Cookie
    if (!token) {
      token = request.cookies.get("umgn_token")?.value;
    }

    if (!token) {
      return NextResponse.json(
        { error: "Authentication required. Please log in." },
        { status: 401 }
      );
    }

    try {
      const { payload } = await jwtVerify(token, key);
      // Attach verified user info to headers for downstream route handlers
      const requestHeaders = new Headers(request.headers);
      requestHeaders.set("x-user-id", payload.userId as string);
      requestHeaders.set("x-user-name", payload.username as string);
      requestHeaders.set("x-user-email", payload.email as string);

      return NextResponse.next({
        request: {
          headers: requestHeaders,
        },
      });
    } catch {
      return NextResponse.json(
        { error: "Invalid or expired session. Please log in again." },
        { status: 401 }
      );
    }
  }

  return NextResponse.next();
}

export const config = {
  matcher: [
    "/api/chats/:path*",
    "/api/chat/:path*",
    "/api/user/:path*",
  ],
};

import { NextRequest, NextResponse } from "next/server";
import { db } from "@/lib/db";
import { hashPassword, signToken, authCookieOptions } from "@/lib/auth";
import { rateLimit } from "@/lib/rate-limit";
import { validateEmail, validateUsername, validatePassword, sanitizeText } from "@/lib/security";

export async function POST(req: NextRequest) {
  try {
    const ip = req.headers.get("x-forwarded-for") || "local-ip";
    const rl = rateLimit(`register:${ip}`, { limit: 10, windowMs: 15 * 60 * 1000 });
    if (!rl.success) {
      return NextResponse.json(
        { error: "Too many registration attempts. Please try again later." },
        { status: 429 }
      );
    }

    const body = await req.json();
    const email = sanitizeText(body.email || "").toLowerCase().trim();
    const username = sanitizeText(body.username || "").trim();
    const password = body.password || "";

    if (!validateEmail(email)) {
      return NextResponse.json({ error: "Please provide a valid email address." }, { status: 400 });
    }

    if (!validateUsername(username)) {
      return NextResponse.json(
        { error: "Username must be 3-30 characters long and contain only letters, numbers, or underscores." },
        { status: 400 }
      );
    }

    const pwCheck = validatePassword(password);
    if (!pwCheck.valid) {
      return NextResponse.json({ error: pwCheck.message }, { status: 400 });
    }

    // Check existing user
    const existing = await db.user.findFirst({
      where: {
        OR: [{ email }, { username }],
      },
    });

    if (existing) {
      if (existing.email === email) {
        return NextResponse.json({ error: "An account with this email already exists." }, { status: 409 });
      }
      return NextResponse.json({ error: "This username is already taken." }, { status: 409 });
    }

    const passwordHash = await hashPassword(password);

    // Create user and default settings
    const user = await db.user.create({
      data: {
        email,
        username,
        passwordHash,
        settings: {
          create: {
            systemPrompt: "You are UMGN, a helpful, precise, and thoughtful personal AI assistant.",
            model: "gemini-1.5-flash",
            temperature: 0.7,
            theme: "dark",
          },
        },
      },
      include: {
        settings: true,
      },
    });

    const token = await signToken({
      userId: user.id,
      username: user.username,
      email: user.email,
    });

    const response = NextResponse.json({
      success: true,
      user: {
        id: user.id,
        username: user.username,
        email: user.email,
        settings: user.settings,
      },
    });

    response.cookies.set(authCookieOptions.name, token, authCookieOptions);
    return response;
  } catch (error) {
    console.error("Registration error:", error);
    return NextResponse.json({ error: "Internal server error during registration." }, { status: 500 });
  }
}

import { NextRequest, NextResponse } from "next/server";
import { db } from "@/lib/db";
import { comparePassword, signToken, authCookieOptions } from "@/lib/auth";
import { rateLimit } from "@/lib/rate-limit";
import { sanitizeText } from "@/lib/security";

export async function POST(req: NextRequest) {
  try {
    const ip = req.headers.get("x-forwarded-for") || "local-ip";
    const rl = rateLimit(`login:${ip}`, { limit: 15, windowMs: 15 * 60 * 1000 });
    if (!rl.success) {
      return NextResponse.json(
        { error: "Too many login attempts. Please wait a few minutes before trying again." },
        { status: 429 }
      );
    }

    const body = await req.json();
    const identifier = sanitizeText(body.identifier || body.email || "").trim().toLowerCase();
    const password = body.password || "";

    if (!identifier || !password) {
      return NextResponse.json({ error: "Please provide your email/username and password." }, { status: 400 });
    }

    // Find user by either email or username
    const user = await db.user.findFirst({
      where: {
        OR: [
          { email: identifier },
          { username: identifier },
        ],
      },
      include: {
        settings: true,
      },
    });

    if (!user) {
      return NextResponse.json({ error: "Invalid credentials." }, { status: 401 });
    }

    const passwordMatch = await comparePassword(password, user.passwordHash);
    if (!passwordMatch) {
      return NextResponse.json({ error: "Invalid credentials." }, { status: 401 });
    }

    const token = await signToken({
      userId: user.id,
      username: user.username,
      email: user.email,
    });

    const response = NextResponse.json({
      success: true,
      user: {
        id: user.id,
        username: user.username,
        email: user.email,
        settings: user.settings,
      },
    });

    response.cookies.set(authCookieOptions.name, token, authCookieOptions);
    return response;
  } catch (error) {
    console.error("Login error:", error);
    return NextResponse.json({ error: "Internal server error during login." }, { status: 500 });
  }
}

import { NextResponse } from "next/server";
import { AUTH_COOKIE_NAME } from "@/lib/auth";

export async function POST() {
  const response = NextResponse.json({ success: true, message: "Logged out successfully" });
  response.cookies.set(AUTH_COOKIE_NAME, "", {
    httpOnly: true,
    secure: process.env.NODE_ENV === "production",
    sameSite: "strict",
    path: "/",
    maxAge: 0, // Invalidate cookie immediately
  });
  return response;
}

import { NextRequest, NextResponse } from "next/server";
import { getAuthUser } from "@/lib/auth";
import { db } from "@/lib/db";

export async function GET(req: NextRequest) {
  try {
    const auth = await getAuthUser(req);
    if (!auth) {
      return NextResponse.json({ user: null }, { status: 200 });
    }

    const user = await db.user.findUnique({
      where: { id: auth.userId },
      select: {
        id: true,
        email: true,
        username: true,
        createdAt: true,
        settings: {
          select: {
            systemPrompt: true,
            model: true,
            temperature: true,
            theme: true,
          },
        },
      },
    });

    if (!user) {
      return NextResponse.json({ user: null }, { status: 200 });
    }

    return NextResponse.json({ user });
  } catch (error) {
    console.error("Auth me check error:", error);
    return NextResponse.json({ error: "Internal server error" }, { status: 500 });
  }
}

