export async function GET(req: NextRequest) {
  try {
    const auth = await getAuthUser(req);
    if (!auth) {
      return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
    }

    const userData = await db.user.findUnique({
      where: { id: auth.userId },
      select: {
        id: true,
        email: true,
        username: true,
        createdAt: true,
        updatedAt: true,
        settings: {
          select: {
            systemPrompt: true,
            model: true,
            temperature: true,
            theme: true,
            updatedAt: true,
          },
        },
        chats: {
          orderBy: { createdAt: "desc" },
          select: {
            id: true,
            title: true,
            pinned: true,
            createdAt: true,
            updatedAt: true,
            messages: {
              orderBy: { createdAt: "asc" },
              select: {
                id: true,
                role: true,
                content: true,
                createdAt: true,
              },
            },
          },
        },
      },
    });

    if (!userData) {
      return NextResponse.json({ error: "User not found" }, { status: 404 });
    }

    const exportPayload = {
      version: "1.0",
      exportDate: new Date().toISOString(),
      metadata: {
        appName: "UMGN Personal AI Chatbot",
        privacyNotice: "This file contains your complete exported conversation history and settings.",
      },
      user: {
        id: userData.id,
        email: userData.email,
        username: userData.username,
        memberSince: userData.createdAt,
      },
      settings: userData.settings,
      totalChats: userData.chats.length,
      totalMessages: userData.chats.reduce((acc, c) => acc + c.messages.length, 0),
      chats: userData.chats,
    };

    const jsonString = JSON.stringify(exportPayload, null, 2);
    const filename = `umgn-export-${userData.username}-${new Date().toISOString().slice(0, 10)}.json`;

    return new Response(jsonString, {
      headers: {
        "Content-Type": "application/json; charset=utf-8",
        "Content-Disposition": `attachment; filename="${filename}"`,
      },
    });
  } catch (error) {
    console.error("Data export error:", error);
    return NextResponse.json({ error: "Failed to export data" }, { status: 500 });
  }
}

