import { NextRequest, NextResponse } from "next/server";
import { getAuthUser } from "@/lib/auth";
import { db } from "@/lib/db";
import { sanitizeText } from "@/lib/security";

export async function GET(req: NextRequest) {
  try {
    const auth = await getAuthUser(req);
    if (!auth) {
      return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
    }

    let settings = await db.userSettings.findUnique({
      where: { userId: auth.userId },
    });

    if (!settings) {
      settings = await db.userSettings.create({
        data: {
          userId: auth.userId,
          systemPrompt: "You are UMGN, a helpful, precise, and thoughtful personal AI assistant.",
          model: "gemini-1.5-flash",
          temperature: 0.7,
          theme: "dark",
        },
      });
    }

    return NextResponse.json({ settings });
  } catch (error) {
    console.error("Get settings error:", error);
    return NextResponse.json({ error: "Failed to get settings" }, { status: 500 });
  }
}

export async function PATCH(req: NextRequest) {
  try {
    const auth = await getAuthUser(req);
    if (!auth) {
      return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
    }

    const body = await req.json();
    const updateData: {
      systemPrompt?: string;
      model?: string;
      temperature?: number;
      theme?: string;
    } = {};

    if (typeof body.systemPrompt === "string") {
      updateData.systemPrompt = sanitizeText(body.systemPrompt).slice(0, 1000);
    }
    if (typeof body.model === "string") {
      const allowedModels = ["gemini-1.5-flash", "gemini-1.5-pro", "gpt-4o", "gpt-4o-mini", "claude-3-5-sonnet"];
      if (allowedModels.includes(body.model)) {
        updateData.model = body.model;
      }
    }
    if (typeof body.temperature === "number" && body.temperature >= 0 && body.temperature <= 2) {
      updateData.temperature = body.temperature;
    }
    if (typeof body.theme === "string" && ["dark", "light", "system"].includes(body.theme)) {
      updateData.theme = body.theme;
    }

    const settings = await db.userSettings.upsert({
      where: { userId: auth.userId },
      update: updateData,
      create: {
        userId: auth.userId,
        systemPrompt: updateData.systemPrompt || "You are UMGN, a helpful, precise, and thoughtful personal AI assistant.",
        model: updateData.model || "gemini-1.5-flash",
        temperature: updateData.temperature ?? 0.7,
        theme: updateData.theme || "dark",
      },
    });

    return NextResponse.json({ settings });
  } catch (error) {
    console.error("Update settings error:", error);
    return NextResponse.json({ error: "Failed to update settings" }, { status: 500 });
  }
}

