"use client";

import React, { useState } from "react";
import ReactMarkdown from "react-markdown";
import remarkGfm from "remark-gfm";
import { Copy, Check, Bot, User, RefreshCw } from "lucide-react";

interface ChatMessageProps {
  id?: string;
  role: "user" | "assistant" | "system";
  content: string;
  isStreaming?: boolean;
  onRegenerate?: () => void;
}

export const ChatMessage: React.FC<ChatMessageProps> = ({
  role,
  content,
  isStreaming = false,
  onRegenerate,
}) => {
  const [copied, setCopied] = useState(false);

  const handleCopyMessage = () => {
    navigator.clipboard.writeText(content);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  if (role === "user") {
    return (
      <div className="flex justify-end my-4 px-4">
        <div className="flex items-start gap-2 max-w-[85%] sm:max-w-[75%] flex-row-reverse">
          <div className="w-8 h-8 rounded-full bg-blue-600 flex items-center justify-center flex-shrink-0 text-white shadow-sm">
            <User className="w-4 h-4" />
          </div>
          <div className="bg-[#2f2f2f] text-[#ececec] px-4 py-2.5 rounded-2xl rounded-tr-none text-sm sm:text-base leading-relaxed break-words whitespace-pre-wrap">
            {content}
          </div>
        </div>
      </div>
    );
  }

  // Assistant message
  return (
    <div className="flex justify-start my-4 px-4 w-full">
      <div className="flex items-start gap-3 w-full max-w-4xl mx-auto">
        <div className="w-8 h-8 rounded-full bg-emerald-600 flex items-center justify-center flex-shrink-0 text-white shadow-sm font-bold text-xs">
          <Bot className="w-4 h-4" />
        </div>

        <div className="flex-1 overflow-hidden">
          <div className="text-xs font-semibold text-gray-400 mb-1 flex items-center gap-1.5">
            <span>UMGN</span>
            <span className="text-[10px] bg-[#2f2f2f] text-gray-300 px-1.5 py-0.5 rounded">AI</span>
          </div>

          <div className="prose prose-invert prose-sm sm:prose-base max-w-none text-[#ececec] leading-relaxed break-words">
            <ReactMarkdown
              remarkPlugins={[remarkGfm]}
              components={{
                code({ node, inline, className, children, ...props }: any) {
                  const match = /language-(\w+)/.exec(className || "");
                  const codeString = String(children).replace(/\n$/, "");

                  if (!inline && match) {
                    return (
                      <CodeBlock language={match[1]} code={codeString} />
                    );
                  }

                  if (!inline && codeString.includes("\n")) {
                    return (
                      <CodeBlock language="text" code={codeString} />
                    );
                  }

                  return (
                    <code
                      className="bg-[#2f2f2f] text-emerald-400 px-1.5 py-0.5 rounded text-xs sm:text-sm font-mono"
                      {...props}
                    >
                      {children}
                    </code>
                  );
                },
                table({ children }) {
                  return (
                    <div className="overflow-x-auto my-3">
                      <table className="min-w-full divide-y divide-gray-700 border border-gray-700 rounded-lg">
                        {children}
                      </table>
                    </div>
                  );
                },
                th({ children }) {
                  return (
                    <th className="bg-[#171717] px-3 py-2 text-left text-xs font-semibold text-gray-200">
                      {children}
                    </th>
                  );
                },
                td({ children }) {
                  return (
                    <td className="px-3 py-2 text-xs sm:text-sm border-t border-gray-700">
                      {children}
                    </td>
                  );
                },
              }}
            >
              {content}
            </ReactMarkdown>

            {isStreaming && <span className="cursor-blink" />}
          </div>

          {!isStreaming && content && (
            <div className="flex items-center gap-2 mt-3 pt-2 text-gray-400">
              <button
                onClick={handleCopyMessage}
                title="Copy response"
                className="flex items-center gap-1.5 px-2 py-1 rounded hover:bg-[#2f2f2f] text-xs transition-colors"
              >
                {copied ? <Check className="w-3.5 h-3.5 text-emerald-400" /> : <Copy className="w-3.5 h-3.5" />}
                <span>{copied ? "Copied" : "Copy"}</span>
              </button>

              {onRegenerate && (
                <button
                  onClick={onRegenerate}
                  title="Regenerate response"
                  className="flex items-center gap-1.5 px-2 py-1 rounded hover:bg-[#2f2f2f] text-xs transition-colors"
                >
                  <RefreshCw className="w-3.5 h-3.5" />
                  <span>Regenerate</span>
                </button>
              )}
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

