export interface ChatItem {
  id: string;
  title: string;
  pinned: boolean;
  createdAt: string;
  updatedAt: string;
  _count?: { messages: number };
}

interface SidebarProps {
  chats: ChatItem[];
  activeChatId: string | null;
  onSelectChat: (chatId: string) => void;
  onNewChat: () => void;
  onDeleteChat: (chatId: string) => void;
  onRenameChat: (chatId: string, newTitle: string) => void;
  username: string;
  email: string;
  onOpenSettings: () => void;
  onLogout: () => void;
  isOpen: boolean;
  onClose: () => void;
  isCollapsed: boolean;
  onToggleCollapse: () => void;
}

export const Sidebar: React.FC<SidebarProps> = ({
  chats,
  activeChatId,
  onSelectChat,
  onNewChat,
  onDeleteChat,
  onRenameChat,
  username,
  email,
  onOpenSettings,
  onLogout,
  isOpen,
  onClose,
  isCollapsed,
  onToggleCollapse,
}) => {
  const [editingId, setEditingId] = useState<string | null>(null);
  const [editTitle, setEditTitle] = useState("");

  const handleStartRename = (e: React.MouseEvent, chat: ChatItem) => {
    e.stopPropagation();
    setEditingId(chat.id);
    setEditTitle(chat.title);
  };

  const handleSaveRename = (e: React.MouseEvent | React.FormEvent, chatId: string) => {
    e.stopPropagation();
    e.preventDefault();
    if (editTitle.trim()) {
      onRenameChat(chatId, editTitle.trim());
    }
    setEditingId(null);
  };

  const handleCancelRename = (e: React.MouseEvent) => {
    e.stopPropagation();
    setEditingId(null);
  };

  // Group chats by date
  const groupChats = (items: ChatItem[]) => {
    const today: ChatItem[] = [];
    const yesterday: ChatItem[] = [];
    const last7Days: ChatItem[] = [];
    const older: ChatItem[] = [];

    const now = new Date();
    const todayStart = new Date(now.getFullYear(), now.getMonth(), now.getDate()).getTime();
    const yesterdayStart = todayStart - 86400000;
    const last7DaysStart = todayStart - 86400000 * 7;

    for (const chat of items) {
      const time = new Date(chat.updatedAt || chat.createdAt).getTime();
      if (time >= todayStart) {
        today.push(chat);
      } else if (time >= yesterdayStart) {
        yesterday.push(chat);
      } else if (time >= last7DaysStart) {
        last7Days.push(chat);
      } else {
        older.push(chat);
      }
    }

    return { today, yesterday, last7Days, older };
  };

  const grouped = groupChats(chats);

  const renderGroup = (title: string, groupItems: ChatItem[]) => {
    if (groupItems.length === 0) return null;

    return (
      <div key={title} className="mb-4">
        <div className="px-3 py-1 text-[11px] font-semibold tracking-wider text-gray-500 uppercase">
          {title}
        </div>
        <div className="space-y-1 mt-1">
          {groupItems.map((chat) => {
            const isActive = chat.id === activeChatId;
            const isEditing = chat.id === editingId;

            return (
              <div
                key={chat.id}
                onClick={() => {
                  onSelectChat(chat.id);
                  if (window.innerWidth < 768) {
                    onClose();
                  }
                }}
                className={`group relative flex items-center justify-between px-3 py-2 text-sm rounded-lg cursor-pointer transition-colors ${
                  isActive
                    ? "bg-[#212121] text-white font-medium"
                    : "text-gray-300 hover:bg-[#212121] hover:text-white"
                }`}
              >
                <div className="flex items-center gap-2.5 overflow-hidden flex-1 mr-1">
                  <MessageSquare className="w-4 h-4 flex-shrink-0 text-gray-400" />
                  {isEditing ? (
                    <form
                      onSubmit={(e) => handleSaveRename(e, chat.id)}
                      onClick={(e) => e.stopPropagation()}
                      className="flex-1 flex items-center gap-1"
                    >
                      <input
                        type="text"
                        autoFocus
                        value={editTitle}
                        onChange={(e) => setEditTitle(e.target.value)}
                        className="bg-[#171717] border border-gray-600 rounded px-1.5 py-0.5 text-xs text-white w-full focus:outline-none focus:border-emerald-500"
                      />
                      <button
                        type="button"
                        onClick={(e) => handleSaveRename(e, chat.id)}
                        className="p-1 hover:text-emerald-400"
                      >
                        <Check className="w-3.5 h-3.5" />
                      </button>
                      <button
                        type="button"
                        onClick={handleCancelRename}
                        className="p-1 hover:text-red-400"
                      >
                        <X className="w-3.5 h-3.5" />
                      </button>
                    </form>
                  ) : (
                    <span className="truncate text-xs sm:text-sm">{chat.title}</span>
                  )}
                </div>

                {!isEditing && (
                  <div className="hidden group-hover:flex items-center gap-1">
                    <button
                      onClick={(e) => handleStartRename(e, chat)}
                      title="Rename chat"
                      className="p-1 hover:text-gray-200 text-gray-400 rounded"
                    >
                      <Edit2 className="w-3.5 h-3.5" />
                    </button>
                    <button
                      onClick={(e) => {
                        e.stopPropagation();
                        onDeleteChat(chat.id);
                      }}
                      title="Delete chat"
                      className="p-1 hover:text-red-400 text-gray-400 rounded"
                    >
                      <Trash2 className="w-3.5 h-3.5" />
                    </button>
                  </div>
                )}
              </div>
            );
          })}
        </div>
      </div>
    );
  };

  return (
    <>
      {/* Mobile backdrop */}
      {isOpen && (
        <div
          onClick={onClose}
          className="fixed inset-0 bg-black/60 z-40 md:hidden backdrop-blur-sm transition-opacity"
        />
      )}

      {/* Sidebar container */}
      <aside
        className={`fixed md:static inset-y-0 left-0 z-50 flex flex-col bg-[#171717] border-r border-[#262626] transition-all duration-200 ease-in-out ${
          isOpen ? "translate-x-0" : "-translate-x-full md:translate-x-0"
        } ${isCollapsed ? "md:w-16" : "w-64 sm:w-72"}`}
      >
        {/* Header */}
        <div className="flex items-center justify-between p-3.5 border-b border-[#262626]">
          {!isCollapsed && (
            <div className="flex items-center gap-2.5">
              <div className="w-7 h-7 rounded-lg bg-gradient-to-tr from-emerald-600 to-teal-500 flex items-center justify-center shadow">
                <Shield className="w-4 h-4 text-white" />
              </div>
              <div className="flex flex-col">
                <span className="font-bold text-sm tracking-wide text-white">UMGN</span>
                <span className="text-[10px] text-gray-400 -mt-0.5">Secure Personal AI</span>
              </div>
            </div>
          )}

          <div className="flex items-center gap-1 ml-auto">
            {/* Collapse toggle (desktop) */}
            <button
              onClick={onToggleCollapse}
              className="hidden md:flex p-1.5 rounded-lg text-gray-400 hover:text-white hover:bg-[#262626] transition-colors"
              title={isCollapsed ? "Expand sidebar" : "Collapse sidebar"}
            >
              {isCollapsed ? <ChevronRight className="w-4 h-4" /> : <ChevronLeft className="w-4 h-4" />}
            </button>

            {/* Mobile close button */}
            <button
              onClick={onClose}
              className="md:hidden p-1.5 rounded-lg text-gray-400 hover:text-white hover:bg-[#262626]"
              title="Close sidebar"
            >
              <X className="w-5 h-5" />
            </button>
          </div>
        </div>

        {/* New Chat Button */}
        <div className="p-3">
          <button
            onClick={() => {
              onNewChat();
              if (window.innerWidth < 768) onClose();
            }}
            className={`flex items-center justify-center gap-2 w-full py-2.5 px-3 rounded-lg border border-gray-700 hover:border-gray-500 bg-[#212121] hover:bg-[#282828] text-white text-sm font-medium transition-all shadow-sm ${
              isCollapsed ? "px-0" : ""
            }`}
            title="New chat"
          >
            <Plus className="w-4 h-4 flex-shrink-0 text-emerald-400" />
            {!isCollapsed && <span>New chat</span>}
          </button>
        </div>

        {/* Chat History List */}
        {!isCollapsed ? (
          <div className="flex-1 overflow-y-auto px-3 py-2">
            {chats.length === 0 ? (
              <div className="text-center py-8 text-xs text-gray-500">
                No chat history yet. Start a new conversation!
              </div>
            ) : (
              <>
                {renderGroup("Today", grouped.today)}
                {renderGroup("Yesterday", grouped.yesterday)}
                {renderGroup("Previous 7 Days", grouped.last7Days)}
                {renderGroup("Older", grouped.older)}
              </>
            )}
          </div>
        ) : (
          <div className="flex-1 overflow-y-auto py-2 flex flex-col items-center gap-2">
            {chats.slice(0, 10).map((chat) => (
              <button
                key={chat.id}
                onClick={() => onSelectChat(chat.id)}
                title={chat.title}
                className={`w-10 h-10 rounded-lg flex items-center justify-center transition-colors ${
                  chat.id === activeChatId
                    ? "bg-[#282828] text-emerald-400"
                    : "text-gray-400 hover:bg-[#282828] hover:text-white"
                }`}
              >
                <MessageSquare className="w-4 h-4" />
              </button>
            ))}
          </div>
        )}

        {/* Footer User Profile & Settings */}
        <div className="p-3 border-t border-[#262626] bg-[#141414]">
          {!isCollapsed ? (
            <div className="flex items-center justify-between gap-2">
              <div className="flex items-center gap-2.5 overflow-hidden flex-1">
                <div className="w-8 h-8 rounded-full bg-emerald-700 flex items-center justify-center text-white font-bold text-xs flex-shrink-0">
                  {username ? username.charAt(0).toUpperCase() : "U"}
                </div>
                <div className="flex flex-col overflow-hidden">
                  <span className="text-xs font-semibold text-gray-200 truncate">{username}</span>
                  <span className="text-[10px] text-gray-400 truncate">{email}</span>
                </div>
              </div>

              <div className="flex items-center gap-1">
                <button
                  onClick={onOpenSettings}
                  title="Settings & Data Controls"
                  className="p-1.5 rounded-lg text-gray-400 hover:text-white hover:bg-[#262626] transition-colors"
                >
                  <Settings className="w-4 h-4" />
                </button>
                <button
                  onClick={onLogout}
                  title="Sign Out"
                  className="p-1.5 rounded-lg text-gray-400 hover:text-red-400 hover:bg-[#262626] transition-colors"
                >
                  <LogOut className="w-4 h-4" />
                </button>
              </div>
            </div>
          ) : (
            <div className="flex flex-col items-center gap-2">
              <button
                onClick={onOpenSettings}
                title="Settings"
                className="p-2 rounded-lg text-gray-400 hover:text-white hover:bg-[#262626]"
              >
                <Settings className="w-4 h-4" />
              </button>
              <button
                onClick={onLogout}
                title="Sign Out"
                className="p-2 rounded-lg text-gray-400 hover:text-red-400 hover:bg-[#262626]"
              >
                <LogOut className="w-4 h-4" />
              </button>
            </div>
          )}
        </div>
      </aside>
    </>
  );
};

"use client";

import React, { useState } from "react";
import {
  X,
  User,
  Sliders,
  Database,
  Download,
  Trash2,
  AlertTriangle,
  Check,
  ShieldCheck,
  Moon,
  Sun,
  Save,
} from "lucide-react";

interface SettingsModalProps {
  isOpen: boolean;
  onClose: () => void;
  user: {
    id: string;
    username: string;
    email: string;
    createdAt?: string;
  };
  settings: {
    systemPrompt: string;
    model: string;
    temperature: number;
    theme: string;
  };
  onSaveSettings: (newSettings: {
    systemPrompt: string;
    model: string;
    temperature: number;
    theme: string;
  }) => Promise<void>;
  onClearChats: () => Promise<void>;
  onDeleteAccount: () => Promise<void>;
}

export const SettingsModal: React.FC<SettingsModalProps> = ({
  isOpen,
  onClose,
  user,
  settings,
  onSaveSettings,
  onClearChats,
  onDeleteAccount,
}) => {
  const [activeTab, setActiveTab] = useState<"general" | "ai" | "data">("general");

  // Form state
  const [systemPrompt, setSystemPrompt] = useState(settings.systemPrompt || "");
  const [model, setModel] = useState(settings.model || "gemini-1.5-flash");
  const [temperature, setTemperature] = useState(settings.temperature ?? 0.7);
  const [theme, setTheme] = useState(settings.theme || "dark");

  const [saving, setSaving] = useState(false);
  const [savedSuccess, setSavedSuccess] = useState(false);
  const [exporting, setExporting] = useState(false);

  // Clear chats modal state
  const [confirmClearChats, setConfirmClearChats] = useState(false);
  const [clearingChats, setClearingChats] = useState(false);

  // Delete account modal state
  const [confirmDeleteAccount, setConfirmDeleteAccount] = useState(false);
  const [deleteConfirmationText, setDeleteConfirmationText] = useState("");
  const [deletingAccount, setDeletingAccount] = useState(false);

  if (!isOpen) return null;

  const handleSave = async () => {
    setSaving(true);
    try {
      await onSaveSettings({
        systemPrompt,
        model,
        temperature,
        theme,
      });
      setSavedSuccess(true);
      setTimeout(() => setSavedSuccess(false), 2500);
    } catch (err) {
      console.error("Failed to save settings:", err);
    } finally {
      setSaving(false);
    }
  };

  const handleExportData = async () => {
    setExporting(true);
    try {
      const res = await fetch("/api/user/export");
      if (!res.ok) throw new Error("Failed to export data");

      const blob = await res.blob();
      const url = window.URL.createObjectURL(blob);
      const a = document.createElement("a");
      a.href = url;
      a.download = `umgn-export-${user.username}-${new Date().toISOString().slice(0, 10)}.json`;
      document.body.appendChild(a);
      a.click();
      window.URL.revokeObjectURL(url);
      document.body.removeChild(a);
    } catch (err) {
      console.error("Export error:", err);
      alert("Failed to export your data. Please try again.");
    } finally {
      setExporting(false);
    }
  };

  const handleExecuteClearChats = async () => {
    setClearingChats(true);
    try {
      await onClearChats();
      setConfirmClearChats(false);
    } catch (err) {
      console.error("Failed to clear chats:", err);
    } finally {
      setClearingChats(false);
    }
  };

  const handleExecuteDeleteAccount = async () => {
    if (deleteConfirmationText !== "DELETE") return;
    setDeletingAccount(true);
    try {
      await onDeleteAccount();
    } catch (err) {
      console.error("Failed to delete account:", err);
      setDeletingAccount(false);
    }
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/75 backdrop-blur-sm animate-fadeIn">
      <div className="bg-[#1e1e1e] border border-[#333333] rounded-2xl w-full max-w-2xl overflow-hidden shadow-2xl flex flex-col max-h-[90vh]">
        {/* Modal Header */}
        <div className="flex items-center justify-between px-6 py-4 border-b border-[#2d2d2d] bg-[#171717]">
          <div className="flex items-center gap-2">
            <Sliders className="w-5 h-5 text-emerald-400" />
            <h2 className="text-lg font-bold text-white">UMGN Settings</h2>
          </div>
          <button
            onClick={onClose}
            className="p-1 rounded-lg text-gray-400 hover:text-white hover:bg-[#282828] transition-colors"
          >
            <X className="w-5 h-5" />
          </button>
        </div>

        {/* Modal Navigation Tabs */}
        <div className="flex border-b border-[#2d2d2d] bg-[#171717] px-6 text-sm">
          <button
            onClick={() => setActiveTab("general")}
            className={`flex items-center gap-2 py-3 px-3 font-medium border-b-2 transition-colors ${
              activeTab === "general"
                ? "border-emerald-500 text-emerald-400"
                : "border-transparent text-gray-400 hover:text-gray-200"
            }`}
          >
            <User className="w-4 h-4" />
            <span>Profile & General</span>
          </button>
          <button
            onClick={() => setActiveTab("ai")}
            className={`flex items-center gap-2 py-3 px-3 font-medium border-b-2 transition-colors ${
              activeTab === "ai"
                ? "border-emerald-500 text-emerald-400"
                : "border-transparent text-gray-400 hover:text-gray-200"
            }`}
          >
            <Sliders className="w-4 h-4" />
            <span>AI Model & Persona</span>
          </button>
          <button
            onClick={() => setActiveTab("data")}
            className={`flex items-center gap-2 py-3 px-3 font-medium border-b-2 transition-colors ${
              activeTab === "data"
                ? "border-emerald-500 text-emerald-400"
                : "border-transparent text-gray-400 hover:text-gray-200"
            }`}
          >
            <Database className="w-4 h-4" />
            <span>Data Controls & Privacy</span>
          </button>
        </div>

        {/* Modal Body */}
        <div className="flex-1 overflow-y-auto p-6 space-y-6">
          {/* General Tab */}
          {activeTab === "general" && (
            <div className="space-y-5">
              <div className="bg-[#262626] p-4 rounded-xl border border-[#383838]">
                <h3 className="text-sm font-semibold text-gray-200 mb-3">User Account Info</h3>
                <div className="grid grid-cols-1 sm:grid-cols-2 gap-3 text-sm">
                  <div>
                    <span className="text-xs text-gray-400 block">Username</span>
                    <span className="text-white font-medium">{user.username}</span>
                  </div>
                  <div>
                    <span className="text-xs text-gray-400 block">Email</span>
                    <span className="text-white font-medium">{user.email}</span>
                  </div>
                </div>
              </div>

              <div>
                <label className="block text-sm font-medium text-gray-300 mb-2">Theme</label>
                <div className="grid grid-cols-2 gap-3">
                  <button
                    type="button"
                    onClick={() => setTheme("dark")}
                    className={`flex items-center justify-center gap-2 p-3 rounded-xl border text-sm font-medium transition-all ${
                      theme === "dark"
                        ? "bg-[#2b2b2b] border-emerald-500 text-white"
                        : "bg-[#212121] border-[#383838] text-gray-400 hover:text-white"
                    }`}
                  >
                    <Moon className="w-4 h-4 text-emerald-400" />
                    <span>Dark Mode</span>
                  </button>
                  <button
                    type="button"
                    onClick={() => setTheme("light")}
                    className={`flex items-center justify-center gap-2 p-3 rounded-xl border text-sm font-medium transition-all ${
                      theme === "light"
                        ? "bg-[#2b2b2b] border-emerald-500 text-white"
                        : "bg-[#212121] border-[#383838] text-gray-400 hover:text-white"
                    }`}
                  >
                    <Sun className="w-4 h-4 text-amber-400" />
                    <span>Light Mode</span>
                  </button>
                </div>
              </div>
            </div>
          )}

          {/* AI Model & Persona Tab */}
          {activeTab === "ai" && (
            <div className="space-y-5">
              <div>
                <label className="block text-sm font-medium text-gray-200 mb-1">
                  Default AI Model
                </label>
                <span className="text-xs text-gray-400 block mb-2">
                  Select model to orchestrate. API keys are handled strictly server-side.
                </span>
                <select
                  value={model}
                  onChange={(e) => setModel(e.target.value)}
                  className="w-full bg-[#262626] border border-[#3d3d3d] rounded-xl px-3.5 py-2.5 text-sm text-white focus:outline-none focus:border-emerald-500"
                >
                  <option value="gemini-1.5-flash">Google Gemini 1.5 Flash (Fast & Capable)</option>
                  <option value="gemini-1.5-pro">Google Gemini 1.5 Pro (Deep Reasoning)</option>
                  <option value="gpt-4o-mini">OpenAI GPT-4o Mini (Efficient)</option>
                  <option value="gpt-4o">OpenAI GPT-4o (Omni Intelligence)</option>
                </select>
              </div>

              <div>
                <div className="flex items-center justify-between mb-1">
                  <label className="text-sm font-medium text-gray-200">
                    Creativity & Temperature ({temperature})
                  </label>
                  <span className="text-xs text-gray-400">
                    {temperature < 0.4 ? "Precise" : temperature > 0.8 ? "Creative" : "Balanced"}
                  </span>
                </div>
                <input
                  type="range"
                  min="0"
                  max="1.5"
                  step="0.1"
                  value={temperature}
                  onChange={(e) => setTemperature(parseFloat(e.target.value))}
                  className="w-full h-2 bg-[#2d2d2d] rounded-lg appearance-none cursor-pointer accent-emerald-500"
                />
              </div>

              <div>
                <label className="block text-sm font-medium text-gray-200 mb-1">
                  System Persona & Custom Instructions
                </label>
                <span className="text-xs text-gray-400 block mb-2">
                  Direct how UMGN speaks, responds, and provides assistance.
                </span>
                <textarea
                  rows={4}
                  value={systemPrompt}
                  onChange={(e) => setSystemPrompt(e.target.value)}
                  placeholder="You are UMGN, a helpful, precise, and thoughtful personal AI assistant."
                  className="w-full bg-[#262626] border border-[#3d3d3d] rounded-xl p-3 text-sm text-white focus:outline-none focus:border-emerald-500 resize-none font-sans"
                />
              </div>
            </div>
          )}

          {/* Data Controls & Privacy Tab */}
          {activeTab === "data" && (
            <div className="space-y-6">
              {/* Privacy Badge */}
              <div className="bg-emerald-950/40 border border-emerald-800/60 rounded-xl p-4 flex items-start gap-3">
                <ShieldCheck className="w-5 h-5 text-emerald-400 flex-shrink-0 mt-0.5" />
                <div className="text-xs text-emerald-200 leading-relaxed">
                  <span className="font-bold block text-emerald-300 mb-0.5">Privacy & GDPR Protected</span>
                  UMGN adheres to data minimization: only your username, email, and password hash are stored. No analytics or tracking trackers. All cloud API keys are maintained strictly server-side.
                </div>
              </div>

              {/* Data Export */}
              <div className="flex items-center justify-between p-4 bg-[#262626] rounded-xl border border-[#383838]">
                <div>
                  <h4 className="text-sm font-semibold text-white">Export Complete Data</h4>
                  <p className="text-xs text-gray-400 mt-0.5">
                    Download a full JSON archive of all your chats, messages, and settings.
                  </p>
                </div>
                <button
                  type="button"
                  onClick={handleExportData}
                  disabled={exporting}
                  className="flex items-center gap-1.5 px-3 py-2 bg-[#333333] hover:bg-[#3f3f3f] text-white text-xs font-medium rounded-lg transition-colors disabled:opacity-50"
                >
                  <Download className="w-4 h-4 text-emerald-400" />
                  <span>{exporting ? "Exporting..." : "Download JSON"}</span>
                </button>
              </div>

              {/* Clear Chats */}
              <div className="flex items-center justify-between p-4 bg-[#262626] rounded-xl border border-[#383838]">
                <div>
                  <h4 className="text-sm font-semibold text-white">Clear All Chats</h4>
                  <p className="text-xs text-gray-400 mt-0.5">
                    Permanently delete all your conversation history while keeping your account.
                  </p>
                </div>
                <button
                  type="button"
                  onClick={() => setConfirmClearChats(true)}
                  className="flex items-center gap-1.5 px-3 py-2 bg-amber-950/50 hover:bg-amber-900/70 border border-amber-800/60 text-amber-200 text-xs font-medium rounded-lg transition-colors"
                >
                  <Trash2 className="w-4 h-4 text-amber-400" />
                  <span>Clear Chats</span>
                </button>
              </div>

              {/* Danger Zone: Delete Account */}
