"use client";

import React, { useRef, useEffect } from "react";
import {
  Menu,
  Send,
  Square,
  Sparkles,
  Shield,
  Code2,
  FileText,
  Lightbulb,
  Search,
} from "lucide-react";
import { ChatMessage } from "./ChatMessage";

interface Message {
  id: string;
  role: "user" | "assistant" | "system";
  content: string;
}

interface ChatAreaProps {
  chatTitle: string;
  messages: Message[];
  inputPrompt: string;
  setInputPrompt: (val: string) => void;
  onSendMessage: (text?: string) => void;
  onStopStreaming: () => void;
  onRegenerate: () => void;
  isStreaming: boolean;
  streamingContent: string;
  onToggleSidebar: () => void;
  modelName: string;
}

const SUGGESTIONS = [
  {
    icon: Code2,
    title: "Write secure code",
    prompt: "Write a production-ready TypeScript function that safely validates and sanitizes input data.",
  },
  {
    icon: Lightbulb,
    title: "Explain a concept",
    prompt: "Explain how public-key cryptography and SSL/TLS certificates work in simple terms.",
  },
  {
    icon: FileText,
    title: "Draft an announcement",
    prompt: "Draft a concise, professional release announcement for our new AI chatbot named UMGN.",
  },
  {
    icon: Search,
    title: "Database optimization",
    prompt: "How can I optimize an SQLite or PostgreSQL database when scaling to thousands of concurrent users?",
  },
];

export const ChatArea: React.FC<ChatAreaProps> = ({
  chatTitle,
  messages,
  inputPrompt,
  setInputPrompt,
  onSendMessage,
  onStopStreaming,
  onRegenerate,
  isStreaming,
  streamingContent,
  onToggleSidebar,
  modelName,
}) => {
  const textareaRef = useRef<HTMLTextAreaElement>(null);
  const messagesEndRef = useRef<HTMLDivElement>(null);

  // Auto-scroll when messages or streaming content changes
  useEffect(() => {
    messagesEndRef.current?.scrollIntoView({ behavior: "smooth" });
  }, [messages, streamingContent]);

  // Adjust textarea height automatically
  const handleInputChange = (e: React.ChangeEvent<HTMLTextAreaElement>) => {
    setInputPrompt(e.target.value);
    if (textareaRef.current) {
      textareaRef.current.style.height = "auto";
      textareaRef.current.style.height = `${Math.min(textareaRef.current.scrollHeight, 200)}px`;
    }
  };

  const handleKeyDown = (e: React.KeyboardEvent<HTMLTextAreaElement>) => {
    if (e.key === "Enter" && !e.shiftKey) {
      e.preventDefault();
      if (!isStreaming && inputPrompt.trim()) {
        onSendMessage();
        if (textareaRef.current) {
          textareaRef.current.style.height = "auto";
        }
      }
    }
  };

  return (
    <main className="flex-1 flex flex-col h-full bg-[#212121] overflow-hidden relative">
      {/* Top Navigation Bar */}
      <header className="h-14 border-b border-[#2d2d2d] flex items-center justify-between px-4 bg-[#212121]/95 backdrop-blur-sm z-10">
        <div className="flex items-center gap-3">
          <button
            onClick={onToggleSidebar}
            className="p-2 rounded-lg text-gray-400 hover:text-white hover:bg-[#2c2c2c] transition-colors"
            title="Toggle Sidebar"
          >
            <Menu className="w-5 h-5" />
          </button>
          <div className="flex items-center gap-2 overflow-hidden">
            <span className="font-semibold text-sm sm:text-base text-gray-100 truncate max-w-[200px] sm:max-w-md">
              {chatTitle || "New Chat"}
            </span>
            <span className="hidden sm:inline-block text-[11px] bg-[#2d2d2d] text-emerald-400 px-2 py-0.5 rounded-full font-medium border border-emerald-900/40">
              {modelName}
            </span>
          </div>
        </div>

        <div className="flex items-center gap-2">
          <div className="flex items-center gap-1.5 px-2 py-1 rounded-full bg-emerald-950/40 border border-emerald-800/40 text-[11px] text-emerald-300">
            <Shield className="w-3.5 h-3.5" />
            <span className="hidden md:inline">Secure Session</span>
          </div>
        </div>
      </header>

      {/* Main Message Stream or Empty State */}
      <div className="flex-1 overflow-y-auto overflow-x-hidden">
        {messages.length === 0 && !isStreaming ? (
          <div className="h-full flex flex-col items-center justify-center p-6 text-center max-w-2xl mx-auto">
            <div className="w-16 h-16 rounded-2xl bg-gradient-to-tr from-emerald-600 to-teal-500 flex items-center justify-center shadow-xl mb-4">
              <Sparkles className="w-8 h-8 text-white" />
            </div>
            <h1 className="text-2xl sm:text-3xl font-bold text-white mb-2 tracking-tight">
              UMGN Personal Assistant
            </h1>
            <p className="text-xs sm:text-sm text-gray-400 max-w-md mb-8">
              Server-side intelligence with zero client-side secret exposure, persistent SQLite/PostgreSQL storage, and full privacy controls.
            </p>

            <div className="grid grid-cols-1 sm:grid-cols-2 gap-3 w-full text-left">
              {SUGGESTIONS.map((item, index) => {
                const Icon = item.icon;
                return (
                  <button
                    key={index}
                    onClick={() => onSendMessage(item.prompt)}
                    className="p-3.5 rounded-xl border border-[#333333] hover:border-emerald-500/50 bg-[#282828] hover:bg-[#2e2e2e] transition-all group"
                  >
                    <div className="flex items-center gap-2 mb-1">
                      <Icon className="w-4 h-4 text-emerald-400 group-hover:scale-110 transition-transform" />
                      <span className="text-xs font-semibold text-gray-200">
                        {item.title}
                      </span>
                    </div>
                    <p className="text-[11px] text-gray-400 line-clamp-2">
                      {item.prompt}
                    </p>
                  </button>
                );
              })}
            </div>
          </div>
        ) : (
          <div className="py-4 max-w-4xl mx-auto w-full">
            {messages.map((m, idx) => (
              <ChatMessage
                key={m.id || idx}
                role={m.role}
                content={m.content}
                onRegenerate={
                  idx === messages.length - 1 && m.role === "assistant" && !isStreaming
                    ? onRegenerate
                    : undefined
                }
              />
            ))}

            {isStreaming && (
              <ChatMessage
                role="assistant"
                content={streamingContent}
                isStreaming={true}
              />
            )}

            <div ref={messagesEndRef} className="h-4" />
          </div>
        )}
      </div>

      {/* Input Form Bar */}
      <footer className="p-3 sm:p-4 bg-[#212121] border-t border-[#2d2d2d]">
        <div className="max-w-3xl mx-auto">
          <div className="relative flex items-end bg-[#2f2f2f] rounded-2xl border border-[#3d3d3d] focus-within:border-emerald-500 shadow-lg px-3 py-2 transition-all">
            <textarea
              ref={textareaRef}
              rows={1}
              value={inputPrompt}
              onChange={handleInputChange}
              onKeyDown={handleKeyDown}
              placeholder="Ask UMGN anything... (Shift+Enter for newline)"
              className="w-full bg-transparent text-white text-sm focus:outline-none resize-none py-1 max-h-48 placeholder-gray-400"
            />

            <div className="ml-2 flex items-center">
              {isStreaming ? (
                <button
                  type="button"
                  onClick={onStopStreaming}
                  className="p-2 rounded-xl bg-gray-600 hover:bg-gray-500 text-white transition-colors"
                  title="Stop generating"
                >
                  <Square className="w-4 h-4 fill-white" />
                </button>
              ) : (
                <button
                  type="button"
                  onClick={() => onSendMessage()}
                  disabled={!inputPrompt.trim()}
                  className="p-2 rounded-xl bg-white hover:bg-gray-200 text-black disabled:opacity-30 disabled:hover:bg-white transition-all shadow-sm"
                  title="Send message"
                >
                  <Send className="w-4 h-4" />
                </button>
              )}
            </div>
          </div>

          <div className="text-center mt-2">
            <span className="text-[11px] text-gray-500">
              UMGN can make mistakes. Verify critical facts and do not input sensitive secrets.
            </span>
          </div>
        </div>
      </footer>
    </main>
  );
};

"use client";

import React, { useState, useEffect, useRef } from "react";
import { Sidebar, ChatItem } from "@/components/Sidebar";
import { ChatArea } from "@/components/ChatArea";
import { AuthModal } from "@/components/AuthModal";
import { SettingsModal } from "@/components/SettingsModal";

interface Message {
  id: string;
  role: "user" | "assistant" | "system";
  content: string;
}

export default function Home() {
  const [user, setUser] = useState<any>(null);
  const [loadingAuth, setLoadingAuth] = useState(true);

  // Chat state
  const [chats, setChats] = useState<ChatItem[]>([]);
  const [activeChatId, setActiveChatId] = useState<string | null>(null);
  const [messages, setMessages] = useState<Message[]>([]);
  const [inputPrompt, setInputPrompt] = useState("");

  // Streaming state
  const [isStreaming, setIsStreaming] = useState(false);
  const [streamingContent, setStreamingContent] = useState("");
  const abortControllerRef = useRef<AbortController | null>(null);

  // UI state
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [isSidebarCollapsed, setIsSidebarCollapsed] = useState(false);
  const [isSettingsOpen, setIsSettingsOpen] = useState(false);

  // Check auth session on load
  useEffect(() => {
    checkAuth();
  }, []);

  const checkAuth = async () => {
    try {
      const res = await fetch("/api/auth/me");
      const data = await res.json();
      if (data.user) {
        setUser(data.user);
        loadChats();
      } else {
        setUser(null);
      }
    } catch (err) {
      console.error("Auth check failed:", err);
      setUser(null);
    } finally {
      setLoadingAuth(false);
    }
  };

  const loadChats = async () => {
    try {
      const res = await fetch("/api/chats");
      if (res.ok) {
        const data = await res.json();
        setChats(data.chats || []);
        if (data.chats?.length > 0 && !activeChatId) {
          // Select most recent chat by default
          loadChatMessages(data.chats[0].id);
        }
      }
    } catch (err) {
      console.error("Failed to load chats:", err);
    }
  };

  const loadChatMessages = async (chatId: string) => {
    setActiveChatId(chatId);
    try {
      const res = await fetch(`/api/chats/${chatId}`);
      if (res.ok) {
        const data = await res.json();
        setMessages(data.chat.messages || []);
      }
    } catch (err) {
      console.error("Failed to load chat messages:", err);
    }
  };

  const handleNewChat = async () => {
    if (isStreaming) return;
    try {
      const res = await fetch("/api/chats", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ title: "New Chat" }),
      });
      if (res.ok) {
        const data = await res.json();
        setChats((prev) => [data.chat, ...prev]);
        setActiveChatId(data.chat.id);
        setMessages([]);
      }
    } catch (err) {
      console.error("Failed to create new chat:", err);
    }
  };

  const handleDeleteChat = async (chatId: string) => {
    try {
      const res = await fetch(`/api/chats/${chatId}`, { method: "DELETE" });
      if (res.ok) {
        setChats((prev) => prev.filter((c) => c.id !== chatId));
        if (activeChatId === chatId) {
          setActiveChatId(null);
          setMessages([]);
        }
      }
    } catch (err) {
      console.error("Failed to delete chat:", err);
    }
  };

  const handleRenameChat = async (chatId: string, newTitle: string) => {
    try {
      const res = await fetch(`/api/chats/${chatId}`, {
        method: "PATCH",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ title: newTitle }),
      });
      if (res.ok) {
        setChats((prev) =>
          prev.map((c) => (c.id === chatId ? { ...c, title: newTitle } : c))
        );
      }
    } catch (err) {
      console.error("Failed to rename chat:", err);
    }
  };

  const handleSendMessage = async (customPrompt?: string) => {
    const textToSend = (customPrompt || inputPrompt).trim();
    if (!textToSend || isStreaming) return;

    let targetChatId = activeChatId;

    // Create chat automatically if none is selected
    if (!targetChatId) {
      try {
        const res = await fetch("/api/chats", {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({ title: textToSend.slice(0, 36) }),
        });
        if (res.ok) {
          const data = await res.json();
          targetChatId = data.chat.id;
          setActiveChatId(targetChatId);
          setChats((prev) => [data.chat, ...prev]);
        }
      } catch (err) {
        console.error("Failed to auto-create chat:", err);
        return;
      }
    }

    if (!targetChatId) return;

    // Optimistically add user message to UI
    const tempUserMsg: Message = {
      id: `temp-${Date.now()}`,
      role: "user",
      content: textToSend,
    };
    setMessages((prev) => [...prev, tempUserMsg]);
    setInputPrompt("");
    setIsStreaming(true);
    setStreamingContent("");

    const controller = new AbortController();
    abortControllerRef.current = controller;

    try {
      const response = await fetch("/api/chat/stream", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          chatId: targetChatId,
          content: textToSend,
        }),
        signal: controller.signal,
      });

      if (!response.ok) {
        const errorData = await response.json();
        throw new Error(errorData.error || "Failed to stream completion");
      }

      const reader = response.body?.getReader();
      if (!reader) throw new Error("No readable stream");

      const decoder = new TextDecoder();
      let accumulated = "";

      while (true) {
        const { done, value } = await reader.read();
        if (done) break;
        const chunk = decoder.decode(value, { stream: true });
        accumulated += chunk;
        setStreamingContent(accumulated);
      }

      // Add finalized assistant message to list
      setMessages((prev) => [
        ...prev,
        {
          id: `asst-${Date.now()}`,
          role: "assistant",
          content: accumulated,
        },
      ]);
      setStreamingContent("");

      // Refresh chat list to update timestamps and generated titles
      loadChats();
    } catch (err: any) {
      if (err.name !== "AbortError") {
        console.error("Streaming error:", err);
        setMessages((prev) => [
          ...prev,
          {
            id: `err-${Date.now()}`,
            role: "assistant",
            content: `⚠️ Error: ${err.message || "Failed to generate response."}`,
          },
        ]);
      }
    } finally {
      setIsStreaming(false);
      abortControllerRef.current = null;
    }
  };

  const handleStopStreaming = () => {
    if (abortControllerRef.current) {
      abortControllerRef.current.abort();
      abortControllerRef.current = null;
    }
    if (streamingContent) {
      setMessages((prev) => [
        ...prev,
        {
          id: `stopped-${Date.now()}`,
          role: "assistant",
          content: streamingContent + " *(Response stopped)*",
        },
      ]);
      setStreamingContent("");
    }
    setIsStreaming(false);
  };

  const handleRegenerate = () => {
    // Find last user message
    const lastUserMsg = [...messages].reverse().find((m) => m.role === "user");
    if (lastUserMsg) {
      // Remove last assistant message
      setMessages((prev) => {
        const next = [...prev];
        if (next[next.length - 1]?.role === "assistant") {
          next.pop();
        }
        return next;
      });
      handleSendMessage(lastUserMsg.content);
    }
  };

  const handleLogout = async () => {
    try {
      await fetch("/api/auth/logout", { method: "POST" });
    } catch (err) {
      console.error("Logout error:", err);
    } finally {
      setUser(null);
      setChats([]);
      setActiveChatId(null);
      setMessages([]);
    }
  };

  const handleSaveSettings = async (newSettings: any) => {
    const res = await fetch("/api/user/settings", {
      method: "PATCH",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(newSettings),
    });
    if (!res.ok) throw new Error("Failed to save settings");
    const data = await res.json();
    setUser((prev: any) => ({
      ...prev,
      settings: data.settings,
    }));
  };

  const handleClearAllChats = async () => {
    const res = await fetch("/api/user/chats", { method: "DELETE" });
    if (!res.ok) throw new Error("Failed to clear chats");
    setChats([]);
    setActiveChatId(null);
    setMessages([]);
  };

  const handleDeleteAccount = async () => {
    const res = await fetch("/api/user/account", { method: "DELETE" });
    if (!res.ok) throw new Error("Failed to delete account");
    setUser(null);
    setChats([]);
    setActiveChatId(null);
    setMessages([]);
    setIsSettingsOpen(false);
  };

  if (loadingAuth) {
    return (
      <div className="h-screen w-screen flex items-center justify-center bg-[#212121] text-white">
        <div className="flex flex-col items-center gap-3">
          <div className="w-8 h-8 border-2 border-emerald-500 border-t-transparent rounded-full animate-spin" />
          <span className="text-xs text-gray-400 font-mono tracking-wider">INITIALIZING UMGN...</span>
        </div>
      </div>
    );
  }

  const activeChat = chats.find((c) => c.id === activeChatId);
  const currentModelName = user?.settings?.model || "gemini-1.5-flash";

  return (
    <div className="flex h-screen w-screen overflow-hidden bg-[#212121]">
      {/* Authentication Modal */}
      <AuthModal
        isOpen={!user}
        onSuccess={(loggedUser) => {
          setUser(loggedUser);
          loadChats();
        }}
      />

      {/* Main Application Interface */}
      {user && (
        <>
          <Sidebar
            chats={chats}
            activeChatId={activeChatId}
            onSelectChat={(id) => loadChatMessages(id)}
            onNewChat={handleNewChat}
            onDeleteChat={handleDeleteChat}
            onRenameChat={handleRenameChat}
            username={user.username}
            email={user.email}
            onOpenSettings={() => setIsSettingsOpen(true)}
            onLogout={handleLogout}
            isOpen={isSidebarOpen}
            onClose={() => setIsSidebarOpen(false)}
            isCollapsed={isSidebarCollapsed}
            onToggleCollapse={() => setIsSidebarCollapsed(!isSidebarCollapsed)}
          />

          <ChatArea
            chatTitle={activeChat?.title || "New Chat"}
            messages={messages}
            inputPrompt={inputPrompt}
            setInputPrompt={setInputPrompt}
            onSendMessage={handleSendMessage}
            onStopStreaming={handleStopStreaming}
            onRegenerate={handleRegenerate}
            isStreaming={isStreaming}
            streamingContent={streamingContent}
            onToggleSidebar={() => setIsSidebarOpen(!isSidebarOpen)}
            modelName={currentModelName}
          />

          <SettingsModal
            isOpen={isSettingsOpen}
            onClose={() => setIsSettingsOpen(false)}
            user={user}
            settings={
              user.settings || {
                systemPrompt: "You are UMGN, a helpful, precise, and thoughtful personal AI assistant.",
                model: "gemini-1.5-flash",
                temperature: 0.7,
                theme: "dark",
              }
            }
            onSaveSettings={handleSaveSettings}
            onClearChats={handleClearAllChats}
            onDeleteAccount={handleDeleteAccount}
          />
        </>
      )}
    </div>
  );
}

