// Automated E2E verification test for UMGN API endpoints
const BASE_URL = "http://localhost:3000";

async function runTests() {
  console.log("=== Starting UMGN Automated Integration Tests ===");

  const testEmail = `testuser_${Date.now()}@example.com`;
  const testUsername = `user_${Date.now()}`;
  const testPassword = "Password123!";

  let sessionCookie = "";

  // 1. Register
  console.log("\n[1/7] Testing Registration...");
  const regRes = await fetch(`${BASE_URL}/api/auth/register`, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({
      email: testEmail,
      username: testUsername,
      password: testPassword,
    }),
  });

  const regData = await regRes.json();
  if (!regRes.ok) {
    throw new Error(`Register failed: ${JSON.stringify(regData)}`);
  }
  console.log("✓ Registration succeeded:", regData.user.username);

  // Extract set-cookie
  const setCookie = regRes.headers.get("set-cookie");
  if (setCookie) {
    sessionCookie = setCookie.split(";")[0];
  }

  // 2. Auth Me Session Check
  console.log("\n[2/7] Testing Session Verification (/api/auth/me)...");
  const meRes = await fetch(`${BASE_URL}/api/auth/me`, {
    headers: { Cookie: sessionCookie },
  });
  const meData = await meRes.json();
  if (!meRes.ok || !meData.user) {
    throw new Error(`Session check failed: ${JSON.stringify(meData)}`);
  }
  console.log("✓ Session verified for user ID:", meData.user.id);

  // 3. Create Chat
  console.log("\n[3/7] Testing Chat Creation (/api/chats)...");
  const chatRes = await fetch(`${BASE_URL}/api/chats`, {
    method: "POST",
    headers: {
      "Content-Type": "application/json",
      Cookie: sessionCookie,
    },
    body: JSON.stringify({ title: "Integration Test Chat" }),
  });
  const chatData = await chatRes.json();
  if (!chatRes.ok || !chatData.chat) {
    throw new Error(`Chat creation failed: ${JSON.stringify(chatData)}`);
  }
  const chatId = chatData.chat.id;
  console.log("✓ Chat created with ID:", chatId);

  // 4. Send & Stream Message
  console.log("\n[4/7] Testing Chat Streaming (/api/chat/stream)...");
  const streamRes = await fetch(`${BASE_URL}/api/chat/stream`, {
    method: "POST",
    headers: {
      "Content-Type": "application/json",
      Cookie: sessionCookie,
    },
    body: JSON.stringify({
      chatId,
      content: "Hello UMGN, can you verify your architecture?",
    }),
  });

  if (!streamRes.ok) {
    const errText = await streamRes.text();
    throw new Error(`Stream failed: ${errText}`);
  }

  const streamText = await streamRes.text();
  console.log(`✓ Received streamed response (${streamText.length} bytes):`);
  console.log(`Preview: "${streamText.slice(0, 100).replace(/\n/g, " ")}..."`);

  // 5. Data Export (GDPR)
  console.log("\n[5/7] Testing Data Export (/api/user/export)...");
  const exportRes = await fetch(`${BASE_URL}/api/user/export`, {
    headers: { Cookie: sessionCookie },
  });
  if (!exportRes.ok) {
    throw new Error("Data export failed");
  }
  const exportJson = await exportRes.json();
  console.log(`✓ Data exported successfully! Contained ${exportJson.totalChats} chat(s) and ${exportJson.totalMessages} message(s).`);

  // 6. Clear Chats
  console.log("\n[6/7] Testing Clear Chats (/api/user/chats)...");
  const clearRes = await fetch(`${BASE_URL}/api/user/chats`, {
    method: "DELETE",
    headers: { Cookie: sessionCookie },
  });
  const clearData = await clearRes.json();
  console.log("✓ Clear chats result:", clearData.message);

  // 7. Delete Account
  console.log("\n[7/7] Testing Permanent Account Deletion (/api/user/account)...");
  const deleteRes = await fetch(`${BASE_URL}/api/user/account`, {
    method: "DELETE",
    headers: { Cookie: sessionCookie },
  });
  const deleteData = await deleteRes.json();
  console.log("✓ Account deletion result:", deleteData.message);

  console.log("\n=======================================================");
  console.log("🎉 ALL INTEGRATION TESTS PASSED SUCCESSFULLY! (7/7)");
  console.log("=======================================================");
}

runTests().catch((err) => {
  console.error("❌ Test failed:", err);
  process.exit(1);
});

